import { spawn } from 'node:child_process';
import { createRequire } from 'node:module';
import net from 'node:net';
import { readdir, open } from 'node:fs/promises';
import { setTimeout as delay } from 'node:timers/promises';

const mode = process.env.CONTROL_MODE ?? 'wrangler';
const connection = process.env.CONTROL_CONNECTION ?? 'close';
if (!['wrangler', 'wrangler-user', 'miniflare', 'direct'].includes(mode) || !['close', 'omit'].includes(connection)) {
  throw new Error('invalid diagnostic mode');
}
const script = process.env.CONTROL_SCRIPT ?? '/private/tmp/edgezero-overflow-cf-sdkless.mjs';
let port = 55881;
let child;
let miniflare;
let logs = '';
function append(bytes) { logs += String(bytes).slice(0, Math.max(0, 65536 - logs.length)); }

async function start() {
  if (!mode.startsWith('wrangler')) {
    const require = createRequire('/Users/ag/.asdf/installs/nodejs/24.12.0/lib/node_modules/wrangler/package.json');
    const { Miniflare, Log, LogLevel, convertV4MiniflareOptions } = require('miniflare');
    class CaptureLog extends Log {
      log(message) { append(`${message}\n`); }
    }
    miniflare = new Miniflare(convertV4MiniflareOptions({
      name: 'cancellation-control', modules: true, scriptPath: script,
      compatibilityDate: '2026-04-22', compatibilityFlags: ['enable_request_signal', 'enable_weak_ref'],
      host: '127.0.0.1', port: mode === 'direct' ? 55882 : port,
      unsafeDirectSockets: mode === 'direct' ? [{ host: '127.0.0.1', port }] : undefined,
      cf: false, log: new CaptureLog(LogLevel.DEBUG),
    }));
    await miniflare.ready;
    return;
  }
  const directory = '/private/tmp/edgezero-pr275-wrangler-logs';
  const before = new Set(await readdir(directory));
  child = spawn('/Users/ag/.asdf/installs/nodejs/24.12.0/bin/wrangler', [
    'dev', script, '--config', '/private/tmp/edgezero-overflow-all-20261021-b/overflow-cloudflare/wrangler.toml',
    '--port', String(port), '--ip', '127.0.0.1', '--local',
    '--persist-to', '/private/tmp/edgezero-overflow-cf-control-state',
  ], { env: { ...process.env, WRANGLER_SEND_METRICS: 'false', WRANGLER_LOG_PATH: '/private/tmp/edgezero-pr275-wrangler-logs' } });
  child.stdout.on('data', append);
  child.stderr.on('data', append);
  for (let index = 0; index < 150 && !logs.includes('Ready on'); index++) {
    if (child.exitCode !== null) throw new Error('runtime exited');
    await delay(100);
  }
  if (!logs.includes('Ready on')) throw new Error('runtime startup timeout');
  if (mode === 'wrangler-user') {
    const files = (await readdir(directory)).filter(file => !before.has(file) && /^wrangler-.*\.log$/.test(file));
    if (files.length !== 1) throw new Error('ambiguous runtime log');
    const handle = await open(`${directory}/${files[0]}`, 'r');
    let text;
    try {
      const buffer = Buffer.alloc(65536);
      const { bytesRead } = await handle.read(buffer, 0, buffer.length, 0);
      text = buffer.subarray(0, bytesRead).toString();
    } finally { await handle.close(); }
    const matches = [...text.matchAll(/"userWorkerUrl":\{"protocol":"http:","hostname":"127\.0\.0\.1","port":"(\d+)"\}/g)];
    if (matches.length !== 1) throw new Error('ambiguous user worker address');
    port = Number(matches[0][1]);
    console.log(JSON.stringify({ event: 'diagnostic-boundary', mode, port, qualification: false }));
  }
}

function complete(bytes) {
  const boundary = bytes.indexOf('\r\n\r\n');
  if (boundary < 0) return false;
  const head = bytes.subarray(0, boundary).toString('latin1');
  const body = bytes.subarray(boundary + 4);
  const length = /^content-length: (\d+)\r?$/im.exec(head);
  if (length) return body.length === Number(length[1]);
  if (!/^transfer-encoding: chunked\r?$/im.test(head)) throw new Error('unframed diagnostic response');
  let position = 0;
  while (true) {
    const end = body.indexOf('\r\n', position);
    if (end < 0) return false;
    const line = body.subarray(position, end).toString('ascii');
    if (!/^[0-9a-f]+$/i.test(line)) throw new Error('invalid diagnostic chunk');
    const length = Number.parseInt(line, 16);
    position = end + 2;
    if (body.length < position + length + 2) return false;
    if (body.subarray(position + length, position + length + 2).toString() !== '\r\n') throw new Error('invalid diagnostic framing');
    position += length + 2;
    if (length === 0) return body.length === position;
  }
}

async function request(label, length) {
  const payload = length === null ? '' : `${length.toString(16)}\r\n${'x'.repeat(length)}\r\n0\r\n\r\n`;
  const wire = `POST /progress/overflow/inbound HTTP/1.1\r\nHost: 127.0.0.1:${port}\r\nx-request-token: ${label}\r\n${connection === 'close' ? 'Connection: close\r\n' : ''}${length === null ? 'Content-Length: 0' : 'Transfer-Encoding: chunked'}\r\n\r\n${payload}`;
  const started = performance.now();
  try {
    const reply = await new Promise((resolve, reject) => {
      const socket = net.connect({ host: '127.0.0.1', port });
      let bytes = Buffer.alloc(0);
      const timer = setTimeout(() => socket.destroy(new Error('absolute diagnostic deadline')), 6000);
      socket.once('close', () => clearTimeout(timer));
      socket.once('connect', () => socket.write(wire));
      socket.on('data', chunk => {
        if (bytes.length + chunk.length > 8192) return socket.destroy(new Error('diagnostic capture bound'));
        bytes = Buffer.concat([bytes, chunk]);
        try {
          if (complete(bytes)) { resolve(bytes.toString()); socket.destroy(); }
        } catch (error) { socket.destroy(error); }
      });
      socket.once('error', reject);
      socket.once('end', () => {
        if (complete(bytes)) resolve(bytes.toString());
        else reject(new Error('incomplete diagnostic response'));
      });
    });
    console.log(JSON.stringify({ event: 'control-request', mode, connection, label, length, elapsed_ms: performance.now() - started, reply }));
  } catch (error) {
    console.log(JSON.stringify({ event: 'control-request', mode, connection, label, length, error: String(error) }));
  }
}

try {
  await start();
  for (const [label, length] of [
    ['baseline', 1024], ['overflow-a', 1025], ['after-a', null], ['recover-a', null],
    ['overflow-b', 1025], ['after-b', 1], ['recover-b', 1],
    ['overflow-c', 1025], ['after-c', 1024], ['recover-c', 1024],
  ]) await request(label, length);
} finally {
  if (miniflare) await miniflare.dispose();
  if (child) {
    const stopped = new Promise(resolve => child.once('close', resolve));
    child.kill('SIGTERM');
    let timer;
    await Promise.race([stopped, new Promise(resolve => { timer = setTimeout(resolve, 5000); })]);
    clearTimeout(timer);
    if (child.exitCode === null && child.signalCode === null) child.kill('SIGKILL');
    await stopped;
  }
  console.log(JSON.stringify({ event: 'runtime-log', mode, connection, logs }));
}

export default {
  async fetch(request) {
    const token = request.headers.get('x-request-token');
    console.log(JSON.stringify({ event: 'control-entry', token }));
    let size = 0;
    if (request.body) {
      const reader = request.body.getReader();
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        size += value.byteLength;
        if (size > 1024) {
          reader.cancel().catch(() => {});
          console.log(JSON.stringify({ event: 'control-return', token, status: 413 }));
          return new Response(JSON.stringify({ error: { kind: 'payload_too_large', message: 'request body too large', status: 413 } }), { status: 413 });
        }
      }
      reader.releaseLock();
    }
    console.log(JSON.stringify({ event: 'control-return', token, status: 200 }));
    return Response.json({ case: 'inbound', received: size, qualification: false });
  }
};
